types.SceSTimerInfo:
typedef struct {
    volatile u32 timerData;
    volatile u32 baseTime;
    volatile s32 prsclNumerator;
    volatile s32 prsclDenominator;
    volatile s32 rsrv[60];
    volatile u32 nowData;
} SceHwTimer;
typedef s32 (*SceSTimerCb)(s32, s32, s32, s32);
typedef struct {
    SceHwTimer *regadr;
    s32 intrcode;
    s32 timid;
    u32 prev_tmcy;
    u32 prev_icnt;
    SceSTimerCb cb;
    u32 totalcount;
    void *common;
} SceSTimerInfo;
typedef struct {
    SceSTimerInfo SYSTMR[4];
    u32 nextid;
} SceSTimerCB;

types.SceSTimerReg:
typedef struct {
    u32 Control;
    u32 N;
    s32 M;
} SceSTimerReg;
